function ThreeModel() {
    try {
        const mountRef = React.useRef(null);
        const sceneRef = React.useRef(null);
        const rendererRef = React.useRef(null);
        const frameRef = React.useRef(null);
        const isDragging = React.useRef(false);
        const previousMousePosition = React.useRef({ x: 0, y: 0 });
        const currentRotation = React.useRef({ x: 0, y: -Math.PI / 2 });
        const isReturning = React.useRef(false);
        const modelRef = React.useRef(null);
        const [isLoaded, setIsLoaded] = React.useState(false);

        React.useEffect(() => {
            if (!mountRef.current) return;

            const scene = new THREE.Scene();
            const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 1000);
            const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
            
            const updateSize = () => {
                const width = mountRef.current?.clientWidth || 300;
                const height = mountRef.current?.clientHeight || 300;
                renderer.setSize(width, height);
                camera.aspect = width / height;
                camera.updateProjectionMatrix();
            };

            renderer.setClearColor(0x000000, 0);
            updateSize();
            mountRef.current.appendChild(renderer.domElement);

            // === Add equirectangular environment map for realistic reflections ===
            const textureLoader = new THREE.TextureLoader();
            textureLoader.load('asset/env.webp', (texture) => {
                texture.mapping = THREE.EquirectangularReflectionMapping;
                scene.environment = texture;
            });
            // === End environment map ===

            // === Improved lighting setup ===
            // Optional: subtle point light for extra fill
            const pointLight = new THREE.PointLight(0xffffff, 0.3, 50);
            pointLight.position.set(0, 5, 10);
            scene.add(pointLight);
            // === End improved lighting ===

            // Add lights
            const ambientLight = new THREE.AmbientLight(0xffffff, 1.0);
            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(10, 10, 5);
            scene.add(ambientLight);
            scene.add(directionalLight);

            camera.position.z = 11;

            // Load GLB model
            const loader = new THREE.GLTFLoader();
            loader.load(
                'asset/infinity_squared_logo.glb',
                (gltf) => {
                    const model = gltf.scene;
                    model.position.set(0, 0, 0);
                    model.rotation.set(0, Math.PI, Math.PI/2);

                    // Animate to target rotation (0, -Math.PI/2, 0)
                    const targetRotation = { x: 0, y: -Math.PI/2, z: 0 };
                    const targetScale = 5;
                    const animationDuration = 1500; // ms
                    const startTime = performance.now();

                    function animateRotation(now) {
                        const elapsed = now - startTime;
                        const t = Math.min(elapsed/animationDuration, 1);

                        // Smoothstep easing
                        const ease = t * t * (3 - 2 * t);

                        // Interpolate rotation
                        model.rotation.x = (1 - ease) * 0 + ease * targetRotation.x;
                        model.rotation.y = (1 - ease) * Math.PI + ease * targetRotation.y;
                        model.rotation.z = (1 - ease) * (Math.PI/2) + ease * targetRotation.z;

                        // Interpolate scale
                        model.scale.set(
                            (1 - ease) * 1 + ease * targetScale,
                            (1 - ease) * 1 + ease * targetScale,
                            (1 - ease) * 1 + ease * targetScale
                        );

                        if (t < 1) {
                            requestAnimationFrame(animateRotation);
                        } else {
                            model.rotation.set(targetRotation.x, targetRotation.y, targetRotation.z);
                        }
                    }
                    requestAnimationFrame(animateRotation);
                    
                    scene.add(model);
                    modelRef.current = model;
                    setIsLoaded(true);
                },
                (progress) => {
                    const percent = progress.total ? (progress.loaded / progress.total) * 100 : 0;
                    console.log('Loading progress:', percent.toFixed(2) + ' %');
                },
                (error) => {
                    console.error('Error loading GLB model:', error);
                    // Fallback to basic geometry if GLB fails
                    const geometry = new THREE.IcosahedronGeometry(1.5, 0);
                    const material = new THREE.MeshPhongMaterial({ 
                        color: 0xffffff, 
                        wireframe: true 
                    });
                    const fallbackMesh = new THREE.Mesh(geometry, material);
                    scene.add(fallbackMesh);
                    modelRef.current = fallbackMesh;
                    setIsLoaded(true);
                }
            );

            sceneRef.current = { scene, camera };
            rendererRef.current = renderer;

            // Setup drag handlers
            const cleanupDrag = setupDragHandlers(
                mountRef.current, 
                sceneRef, 
                isDragging, 
                previousMousePosition, 
                currentRotation, 
                isReturning
            );

            const animate = () => {
                frameRef.current = requestAnimationFrame(animate);
                
                if (modelRef.current && isReturning.current) {
                    currentRotation.current.x += (0 - currentRotation.current.x) * 0.05;
                    currentRotation.current.y += (-Math.PI / 2 - currentRotation.current.y) * 0.05;
                    
                    if (Math.abs(currentRotation.current.x) < 0.01 && Math.abs(currentRotation.current.y) < 0.01) {
                        currentRotation.current.x = 0;
                        currentRotation.current.y = -Math.PI / 2;
                        isReturning.current = false;
                    }
                    
                    modelRef.current.rotation.x = currentRotation.current.x;
                    modelRef.current.rotation.y = currentRotation.current.y;
                } else if (modelRef.current && isDragging.current) {
                    modelRef.current.rotation.x = currentRotation.current.x;
                    modelRef.current.rotation.y = currentRotation.current.y;
                }
                
                renderer.render(scene, camera);
            };

            animate();
            window.addEventListener('resize', updateSize);

            return () => {
                if (frameRef.current) cancelAnimationFrame(frameRef.current);
                if (mountRef.current && renderer.domElement) {
                    mountRef.current.removeChild(renderer.domElement);
                }
                window.removeEventListener('resize', updateSize);
                cleanupDrag();
                renderer.dispose();
            };
        }, []);

        // List of random texts
        const randomTexts = [
            "Small team, infinite solutions. Get ready for 3D brilliance!",
            "Blending pixels for you. Your 3D model is almost here!",
            "No tech challenge too big. Loading our immersive 3D world!",
            "From our startup to your screen: A 3D masterpiece awaits!",
            "Innovating at the speed of infinity. Your 3D experience is loading!",
            "Crafting 3D magic with passion. Your model is on its way!",
            "Turning ideas into 3D reality. Loading your immersive experience!",
            "Where creativity meets technology. Your 3D model is loading!",
        ];
        // Pick a random text
        const [randomText] = React.useState(
            randomTexts[Math.floor(Math.random() * randomTexts.length)]
        );

        return (
            <div 
            data-name="three-model" 
            data-file="lib/components/ThreeModel.min.js" 
            ref={mountRef} 
            className="w-full h-full cursor-grab active:cursor-grabbing select-none"
            >
            {!isLoaded && (
                <div className="absolute inset-0 flex items-center justify-center">
                    <div className="text-black text-sm text-center">{randomText}</div>
                </div>
            )}
            </div>
        );
    } catch (error) {
        console.error('ThreeModel component error:', error);
        reportError(error);
    }
}
